pm.test("TC-01: Retrieve a valid cat fact", function () {
    pm.response.to.have.status(200);
    pm.response.to.be.json;

    const response = pm.response.json();

    pm.expect(response.fact).to.be.a("string").and.not.empty;
    pm.expect(response.length).to.be.a("number");
    pm.expect(Number.isInteger(response.length)).to.be.true;
    pm.expect(response.length).to.equal(response.fact.length);
    pm.expect(response.length).to.be.at.most(150);
});

pm.test("TC-02: Retrieve a limited list of cat facts", function () {
    pm.response.to.have.status(200);
    pm.response.to.be.json;

    const response = pm.response.json();

    pm.expect(response.data).to.be.an("array");
    pm.expect(response.data.length).to.be.greaterThan(0);
    pm.expect(response.data.length).to.be.at.most(5);

    response.data.forEach(fact => {
        pm.expect(fact.fact).to.be.a("string").and.not.empty;
        pm.expect(fact.length).to.be.a("number");
        pm.expect(Number.isInteger(fact.length)).to.be.true;
        pm.expect(fact.length).to.equal(fact.fact.length);
    });
});

pm.test("TC-03: Retrieve a limited list of cat breeds", function () {
    pm.response.to.have.status(200);
    pm.response.to.be.json;

    const response = pm.response.json();

    pm.expect(response.data).to.be.an("array");
    pm.expect(response.data.length).to.be.greaterThan(0);
    pm.expect(response.data.length).to.be.at.most(5);

    response.data.forEach(breed => {
        pm.expect(breed.breed).to.be.a("string").and.not.empty;
        pm.expect(breed.country).to.be.a("string");
        pm.expect(breed.origin).to.be.a("string");
        pm.expect(breed.coat).to.be.a("string");
        pm.expect(breed.pattern).to.be.a("string");
    });
});
